package main

import (
	"fmt"
	"image/color"
	"reflect"
)

func rgba8(r, g, b, a uint8) color.RGBA { return color.RGBA{r, g, b, a} }

// ---------------------------------------------------------------------------
// Corrections to the game's own scenarios (editor debug mode).
//
// The 21 campaign scenarios are generated by code. Editing one in the editor
// saves an "override" in assets/backgrounds/<key> (LevelMeta.Override holds the
// key). The game builds the scenario as always and then applies only what the
// override changed compared with a fresh export of the original: objects,
// points, animals, and the walls / water / slow ground / roads / walkable
// zones, cell by cell. Everything else (the generated drawing, highway
// lanes, railway, ship hulls, signs, floors...) stays exactly as generated.
// The background picture of an override is not used.
// ---------------------------------------------------------------------------

// campaignKey is the stable name of the i-th (0 based) campaign scenario.
func campaignKey(i int) string {
	if i < 0 || i >= len(campaignLevels) {
		return ""
	}
	return fmt.Sprintf("c%02d_%s", i+1, campaignLevels[i].icon)
}

// levelOverrides are the overrides found on disk, by campaign key. rebuildLevels fills it.
var levelOverrides = map[string]*LevelAsset{}

// splitLevels separates the scenarios made by the user from the corrections of the originals.
func splitLevels(all []*LevelAsset) (custom []*LevelAsset, overrides map[string]*LevelAsset) {
	overrides = map[string]*LevelAsset{}
	for _, la := range all {
		if la.Meta.Override != "" {
			overrides[la.Meta.Override] = la
		} else {
			custom = append(custom, la)
		}
	}
	return
}

// levelIndexByName is the position in levelDefs of the scenario called name (after rebuildLevels).
func (g *Game) levelIndexByName(name string) int {
	if g.store == nil {
		return 0
	}
	custom, ov := splitLevels(g.store.Levels)
	if len(custom) > 0 {
		for i, la := range custom {
			if la.Meta.Name == name {
				return i
			}
		}
		return 0
	}
	for key, la := range ov {
		if la.Meta.Name == name {
			for i := range campaignLevels {
				if campaignKey(i) == key {
					return i
				}
			}
		}
	}
	return 0
}

func pointsOf(l []LevelPoint) []Vec {
	var out []Vec
	for _, p := range l {
		out = append(out, Vec{float64(p.X) / wk, float64(p.Y) / wk})
	}
	return out
}

// applyLevelOverride patches the generated scenario d with what the override la changed.
func applyLevelOverride(d *LevelDef, la *LevelAsset) {
	base := levelAssetFromDef(d, "base").Meta
	m := la.Meta
	toV := func(p LevelPoint) Vec { return Vec{float64(p.X) / wk, float64(p.Y) / wk} }
	if m.Title != "" && m.Title != base.Title {
		d.Title = m.Title
	}
	if m.Intro != base.Intro {
		d.Intro = m.Intro
	}
	if m.Guests > 0 && m.Guests != base.Guests {
		d.Guests = m.Guests
	}
	if m.Start != base.Start {
		d.Start = toV(m.Start)
	}
	if m.CarFrom != base.CarFrom {
		d.CarFrom = toV(m.CarFrom)
	}
	if m.CarTo != base.CarTo {
		d.CarTo = toV(m.CarTo)
	}
	if !reflect.DeepEqual(m.Pads, base.Pads) {
		d.Pads = pointsOf(m.Pads)
	}
	if !reflect.DeepEqual(m.Guards, base.Guards) {
		d.Guards = nil
		for _, r := range m.Guards {
			if route := pointsOf(r); len(route) > 0 {
				d.Guards = append(d.Guards, route)
			}
		}
	}
	if !reflect.DeepEqual(m.Performers, base.Performers) {
		old := d.Performers
		d.Performers = nil
		for _, p := range m.Performers {
			pos := Vec{float64(p.X) / wk, float64(p.Y) / wk}
			pf := Perf{Pos: pos, Role: p.Role, Dir: DirDown}
			for _, o := range old { // the one that was already there keeps the way it faces
				if o.Role == p.Role && int(o.Pos.X+0.5) == p.X && int(o.Pos.Y+0.5) == p.Y {
					pf.Dir = o.Dir
				}
			}
			d.Performers = append(d.Performers, pf)
		}
	}
	if !reflect.DeepEqual(m.Lights, base.Lights) {
		d.Glows = nil
		for _, l := range m.Lights {
			d.Glows = append(d.Glows, Glow{Pos: Vec{float64(l.X) / wk, float64(l.Y) / wk}, Col: rgba8(l.Color[0], l.Color[1], l.Color[2], l.Alpha), R: float64(l.R) / wk, Pulse: l.Pulse})
		}
	}
	if !reflect.DeepEqual(m.Animals, base.Animals) {
		d.Animals = nil
		for _, an := range m.Animals {
			r := float64(an.Radius) / wk
			if r < 20 {
				r = 60
			}
			c := Vec{float64(an.X) / wk, float64(an.Y) / wk}
			d.Animals = append(d.Animals, AnimalSpawn{Kind: an.Kind, Pos: c, Area: Rect{c.X - r, c.Y - r*0.7, 2 * r, 1.4 * r}})
		}
	}
	if !reflect.DeepEqual(m.Props, base.Props) {
		d.Props = nil
		for _, p := range m.Props {
			if _, ok := propKinds[p.Kind]; !ok {
				continue
			}
			d.Props = append(d.Props, PropInst{Kind: p.Kind, X: float64(p.X) / wk, Y: float64(p.Y) / wk, Var: p.Var})
		}
	}
	// ground and water: the generator draws the background from these lists, so replacing them
	// makes it paint the moved helipad / pool / dance floor / rug where the user put it
	regrid := false
	if !reflect.DeepEqual(m.Floors, base.Floors) && len(m.Floors) > 0 {
		d.Floors = nil
		for _, f := range m.Floors {
			d.Floors = append(d.Floors, Floor{R: Rect{float64(f.X) / wk, float64(f.Y) / wk, float64(f.W) / wk, float64(f.H) / wk}, Kind: f.Kind, Color: f.Color})
		}
		regrid = true
	}
	if len(m.Floors) > 0 && !reflect.DeepEqual(m.Pools, base.Pools) { // (files from before floors were saved lack both lists)
		d.Pools = nil
		for _, p := range m.Pools {
			d.Pools = append(d.Pools, Rect{float64(p.X) / wk, float64(p.Y) / wk, float64(p.W) / wk, float64(p.H) / wk})
		}
		regrid = true
	}
	if regrid {
		// the water and dance cells follow the lists: measure the cell edits against the new ones
		base = levelAssetFromDef(d, "base").Meta
	}
	patchGrids(d, base, m)
}

// cloneDef copies a scenario definition with its own slices, so that an override can be
// applied to the copy without touching the original (the editor does this on every move).
func cloneDef(d *LevelDef) *LevelDef {
	c := *d
	c.Pads = append([]Vec(nil), d.Pads...)
	c.Performers = append([]Perf(nil), d.Performers...)
	c.Doors = append([]Door(nil), d.Doors...)
	c.Animals = append([]AnimalSpawn(nil), d.Animals...)
	c.Glows = append([]Glow(nil), d.Glows...)
	c.Floors = append([]Floor(nil), d.Floors...)
	c.Walls = append([]Wall(nil), d.Walls...)
	c.Props = append([]PropInst(nil), d.Props...)
	c.Pools = append([]Rect(nil), d.Pools...)
	c.Roam = append([]Rect(nil), d.Roam...)
	c.Dance = append([]Rect(nil), d.Dance...)
	c.Roads = append([]RoadSeg(nil), d.Roads...)
	c.Slow = append([]Rect(nil), d.Slow...)
	c.Windows = append([]Rect(nil), d.Windows...)
	c.Guards = nil
	for _, r := range d.Guards {
		c.Guards = append(c.Guards, append([]Vec(nil), r...))
	}
	c.Strobe = append([]uint32(nil), d.Strobe...)
	c.roadsDrawn = false
	return &c
}

// subtractRect cuts cut out of r and returns what is left (up to four rectangles).
func subtractRect(r, cut Rect) []Rect {
	if overlapArea(r, cut) == 0 {
		return []Rect{r}
	}
	var out []Rect
	if cut.Y > r.Y { // above
		out = append(out, Rect{r.X, r.Y, r.W, cut.Y - r.Y})
	}
	if cut.Y+cut.H < r.Y+r.H { // below
		out = append(out, Rect{r.X, cut.Y + cut.H, r.W, r.Y + r.H - cut.Y - cut.H})
	}
	y0, y1 := maxF(r.Y, cut.Y), minF(r.Y+r.H, cut.Y+cut.H)
	if cut.X > r.X { // left
		out = append(out, Rect{r.X, y0, cut.X - r.X, y1 - y0})
	}
	if cut.X+cut.W < r.X+r.W { // right
		out = append(out, Rect{cut.X + cut.W, y0, r.X + r.W - cut.X - cut.W, y1 - y0})
	}
	return out
}

func maxF(a, b float64) float64 {
	if a > b {
		return a
	}
	return b
}

func minF(a, b float64) float64 {
	if a < b {
		return a
	}
	return b
}

// cutRects removes every cut from the rectangles. Slivers thinner than half a cell are dropped.
func cutRects(rs []Rect, cuts []Rect) []Rect {
	k := float64(logicCell) / wk
	for _, c := range cuts {
		var next []Rect
		for _, r := range rs {
			for _, p := range subtractRect(r, c) {
				if p.W >= k/2 && p.H >= k/2 {
					next = append(next, p)
				}
			}
		}
		rs = next
	}
	return rs
}

// changedCells lists, as rectangles in design units, the cells where pick(old,new) is true.
func changedCells(old, now []string, pick func(o, n byte) bool) []Rect {
	rows := make([]string, len(old))
	any := false
	for y := range old {
		row := make([]byte, len(old[y]))
		for x := range row {
			row[x] = '.'
			if y < len(now) && x < len(now[y]) && pick(old[y][x], now[y][x]) {
				row[x] = 'x'
				any = true
			}
		}
		rows[y] = string(row)
	}
	if !any {
		return nil
	}
	var out []Rect
	for _, r := range mergeCells(rows, func(c byte) bool { return c == 'x' }) {
		out = append(out, cellRectToDesign(r))
	}
	return out
}

// patchGrids applies the cell by cell differences between the original and the edited grids.
func patchGrids(d *LevelDef, base, now LevelMeta) {
	if len(now.Solid) != len(base.Solid) || len(now.Zone) != len(base.Zone) {
		return
	}
	// what was removed (the cell held ch and no longer does) and what was added
	gone := func(ch byte) []Rect {
		return changedCells(base.Solid, now.Solid, func(o, n byte) bool { return o == ch && n != ch })
	}
	came := func(ch byte) []Rect {
		return changedCells(base.Solid, now.Solid, func(o, n byte) bool { return n == ch && o != ch })
	}
	fence := func(w Wall) bool { return w.Style == WallFence }
	cutWalls := func(cuts []Rect, keep func(Wall) bool) {
		if len(cuts) == 0 {
			return
		}
		var out []Wall
		for _, w := range d.Walls {
			if !keep(w) { // not the kind being cut
				out = append(out, w)
				continue
			}
			for _, r := range cutRects([]Rect{w.R}, cuts) {
				out = append(out, Wall{R: r, Style: w.Style})
			}
		}
		d.Walls = out
	}
	cutWalls(gone('#'), func(w Wall) bool { return !fence(w) })
	cutWalls(gone('='), fence)
	cutWalls(gone('w'), fence)
	if c := gone('~'); len(c) > 0 {
		d.Pools = cutRects(d.Pools, c)
	}
	if c := gone(','); len(c) > 0 {
		d.Slow = cutRects(d.Slow, c)
	}
	if c := gone('w'); len(c) > 0 {
		d.Windows = cutRects(d.Windows, c)
	}
	for dir, ch := range []byte{'>', '<', '^', 'v'} {
		c := gone(ch)
		if len(c) == 0 {
			continue
		}
		var out []RoadSeg
		for _, rs := range d.Roads {
			if rs.Dir != dir {
				out = append(out, rs)
				continue
			}
			for _, r := range cutRects([]Rect{rs.R}, c) {
				out = append(out, RoadSeg{R: r, Dir: dir})
			}
		}
		d.Roads = out
	}
	for _, r := range came('#') {
		d.Walls = append(d.Walls, Wall{R: r, Style: WallPlaster})
	}
	for _, r := range came('=') {
		d.Walls = append(d.Walls, Wall{R: r, Style: WallFence})
	}
	d.Pools = append(d.Pools, came('~')...)
	d.Slow = append(d.Slow, came(',')...)
	for _, r := range came('w') {
		d.Windows = append(d.Windows, r)
		d.Walls = append(d.Walls, Wall{R: r, Style: WallFence})
	}
	for dir, ch := range []byte{'>', '<', '^', 'v'} {
		for _, r := range came(ch) {
			d.Roads = append(d.Roads, RoadSeg{R: r, Dir: dir})
		}
	}
	// walkable zones: 'r' guests wander, 'd' dance floor (a dance cell is also a wander cell)
	walk := func(c byte) bool { return c == 'r' || c == 'd' }
	if c := changedCells(base.Zone, now.Zone, func(o, n byte) bool { return walk(o) && !walk(n) }); len(c) > 0 {
		d.Roam = cutRects(d.Roam, c)
	}
	if c := changedCells(base.Zone, now.Zone, func(o, n byte) bool { return o == 'd' && n != 'd' }); len(c) > 0 {
		d.Dance = cutRects(d.Dance, c)
	}
	d.Roam = append(d.Roam, changedCells(base.Zone, now.Zone, func(o, n byte) bool { return walk(n) && !walk(o) })...)
	d.Dance = append(d.Dance, changedCells(base.Zone, now.Zone, func(o, n byte) bool { return n == 'd' && o != 'd' })...)
}

func isCampaignKey(name string) bool {
	for i := range campaignLevels {
		if campaignKey(i) == name {
			return true
		}
	}
	return false
}
